INSERT INTO `chatbot_kb` (`title`, `content`, `category`, `active`, `created_at`, `updated_at`) VALUES
('Horaires d''ouverture', 'Nufotec Burundi est ouvert du lundi au vendredi de 8h00 a 17h00. Le service client est joignable par telephone et par email pendant ces heures.', 'General', 1, NOW(), NOW()),
('Nos services', 'Nufotec Burundi propose : 1) La telemedecine (consultations en ligne avec des medecins qualifies), 2) L''e-commerce de produits agro-alimentaires et phyto-medicinaux, 3) Les services d''investissement et de courtage, 4) Une plateforme de medias (audio/video).', 'Services', 1, NOW(), NOW()),
('Contact et telephone', 'Pour nous contacter : Telephone/WhatsApp : +257 79 666 439, Email : info@nufotec.bi, Site web : nufotec.bi. Nous sommes situes a Bujumbura, Burundi.', 'Contact', 1, NOW(), NOW()),
('Comment passer une commande', 'Pour passer une commande : 1) Parcourez notre catalogue de produits sur la page boutique, 2) Selectionnez le produit souhaite, 3) Cliquez sur Commander via WhatsApp, 4) Envoyez votre commande via WhatsApp. Un agent confirmera votre commande.', 'E-commerce', 1, NOW(), NOW()),
('Consultation medicale en ligne', 'Pour une consultation medicale en ligne : 1) Rendez-vous sur la page Consultation, 2) Remplissez le formulaire avec vos symptomes, 3) Choisissez un medecin disponible, 4) Effectuez le paiement, 5) Recevez un lien pour la consultation video. Consultation disponible du lundi au vendredi.', 'Sante', 1, NOW(), NOW()),
('Modes de paiement', 'Nous acceptons : 1) Mobile Money (Lumicash, EcoCash), 2) Virement bancaire, 3) Paiement en especes (pour les livraisons a Bujumbura). Les paiements sont securises.', 'Paiement', 1, NOW(), NOW()),
('Zone de livraison', 'La livraison est disponible dans tout le Burundi. Livraison gratuite a Bujumbura pour les commandes superieures a 50000 BIF. Delai de livraison : 24-48h a Bujumbura, 3-5 jours pour les autres villes.', 'Livraison', 1, NOW(), NOW()),
('Comment devenir investisseur', 'Pour devenir investisseur chez Nufotec : 1) Rendez-vous sur la page Investissement, 2) Remplissez le formulaire d''expression d''interet, 3) Un courtier vous contactera pour discuter des details, 4) Choisissez votre phase d''investissement. Investissement minimum : 500 USD.', 'Investissement', 1, NOW(), NOW()),
('FAQ - Probleme de connexion', 'Si vous avez un probleme de connexion : 1) Verifiez votre connexion internet, 2) Videz le cache de votre navigateur, 3) Essayez un autre navigateur, 4) Si le probleme persiste, contactez-nous au +257 79 666 439.', 'Support', 1, NOW(), NOW()),
('A propos de Nufotec', 'Nufotec Burundi est une entreprise technologique dediee a la promotion de la medecine complementaire et alternative integree. Notre mission : contribuer a l''amelioration de la sante et la nutrition au Burundi via des solutions innovantes.', 'General', 1, NOW(), NOW());
